package br.edu.cesar.treinoconecta.treinoconectacore.infraestrutura.core.aula;

import java.time.*;import java.util.*;
import br.edu.cesar.treinoconecta.treinoconectacore.dominio.core.aula.*;import br.edu.cesar.treinoconecta.treinoconectacore.dominio.core.aula.spi.IAulaRepositorio;
import br.edu.cesar.treinoconecta.treinoconectacore.dominio.core.aluno.AlunoIdentificador;import br.edu.cesar.treinoconecta.treinoconectacore.dominio.core.profissional.ProfissionalIdentificador;
import dev.sauloaraujo.d5.framework.infraestrutura.AgregadoRepositorioAbstrato;import org.springframework.transaction.annotation.Transactional;

public class AulaRepositorio extends AgregadoRepositorioAbstrato<AulaIdentificador,Aula,Long,AulaJpa> implements IAulaRepositorio {
 private final IAulaRepositorioJpa aulas; private final IAulaInscricaoRepositorioJpa inscricoes; private final IAulaNotificacaoRepositorioJpa notificacoes;
 public AulaRepositorio(IAulaRepositorioJpa aulas,IAulaInscricaoRepositorioJpa inscricoes,IAulaNotificacaoRepositorioJpa notificacoes){super(aulas,"Aula %s não encontrada");this.aulas=Objects.requireNonNull(aulas);this.inscricoes=Objects.requireNonNull(inscricoes);this.notificacoes=Objects.requireNonNull(notificacoes);}
 protected Long paraIdentificadorJpa(AulaIdentificador id){return Long.valueOf(id.toString());}
 protected AulaJpa paraJpa(Aula a){return new AulaJpa(a.getIdentificador().map(x->Long.valueOf(x.toString())).orElse(null),a.titulo(),a.modalidade(),a.descricao().orElse(null),a.data(),a.periodo().inicio(),a.periodo().fim(),a.limite(),a.situacao().name(),Long.valueOf(a.professor().toString()),OffsetDateTime.now());}
 protected Aula paraAgregado(AulaJpa j){return new Aula(Optional.of(new AulaIdentificador(j.getIdentificador().toString())),j.getTitulo(),j.getModalidade(),Optional.ofNullable(j.getDescricao()),j.getData(),new PeriodoAula(j.getInicio(),j.getFim()),j.getLimite(),new ProfissionalIdentificador(j.getProfessor().toString()),SituacaoAula.valueOf(j.getStatus()));}
 public Aula bloquear(AulaIdentificador id){return paraAgregado(aulas.bloquear(paraIdentificadorJpa(id)).orElseThrow(()->new NoSuchElementException("Aula não encontrada")));}
 public boolean existeChoque(ProfissionalIdentificador p,LocalDate d,LocalTime i,LocalTime f,Optional<AulaIdentificador> ignorada){return aulas.existeChoque(Long.valueOf(p.toString()),d,i,f,ignorada.map(this::paraIdentificadorJpa).orElse(-1L));}
 public int contarInscritos(AulaIdentificador id){return Math.toIntExact(inscricoes.countByAulaAndStatus(paraIdentificadorJpa(id),"AGENDADO"));}
 public boolean existeInscricaoAtiva(AulaIdentificador id,AlunoIdentificador aluno){return inscricoes.existsByAulaAndAlunoAndStatus(paraIdentificadorJpa(id),Long.valueOf(aluno.toString()),"AGENDADO");}
 @Transactional public void inscrever(AulaIdentificador id,AlunoIdentificador aluno,OffsetDateTime instante){Long aula=paraIdentificadorJpa(id);Long alunoId=Long.valueOf(aluno.toString());var existente=inscricoes.findByAulaAndAluno(aula,alunoId);if(existente.isPresent()){var inscricao=existente.orElseThrow();if(inscricao.getStatus().equals("AGENDADO"))throw new IllegalStateException("Você já está inscrito nesta aula.");inscricao.agendar(instante);inscricoes.save(inscricao);return;}inscricoes.save(new AulaInscricaoJpa(aula,alunoId,"AGENDADO",instante));}
 @Transactional public boolean cancelarInscricao(Long id,AlunoIdentificador aluno,OffsetDateTime agora){var opt=inscricoes.findByIdentificadorAndAlunoAndStatus(id,Long.valueOf(aluno.toString()),"AGENDADO");if(opt.isEmpty())return false;var i=opt.orElseThrow();var aula=aulas.findById(i.getAula()).orElseThrow();if(agora.isAfter(aula.getData().atTime(aula.getInicio()).atZone(ZoneId.of("America/Sao_Paulo")).toOffsetDateTime().minusMinutes(30)))return false;i.cancelar("CANCELADO",agora);inscricoes.save(i);return true;}
 @Transactional public boolean cancelarInscricaoGestao(Long id,OffsetDateTime agora){var opt=inscricoes.findById(id);if(opt.isEmpty()||!opt.orElseThrow().getStatus().equals("AGENDADO"))return false;opt.orElseThrow().cancelar("CANCELADO",agora);inscricoes.save(opt.orElseThrow());return true;}
 @Transactional public void cancelarInscritos(AulaIdentificador id,String titulo,OffsetDateTime instante){Long aula=paraIdentificadorJpa(id);var ativos=inscricoes.findByAulaAndStatus(aula,"AGENDADO");for(var i:ativos){i.cancelar("CANCELADO_PELA_ACADEMIA",instante);notificacoes.save(new NotificacaoAulaJpa(aula,i.getAluno(),"A aula '"+titulo+"' foi cancelada pela academia.",instante));}inscricoes.saveAll(ativos);}
}
